(window.webpackJsonp=window.webpackJsonp||[]).push([[215],{541:function(n,t,e){"use strict";e.r(t);var a=e(33),r=Object(a.a)({},function(){var n=this,t=n.$createElement,e=n._self._c||t;return e("ContentSlotsDistributor",{attrs:{"slot-key":n.$parent.slotKey}},[e("h1",{attrs:{id:"vad-som-hander-i-svetsen"}},[e("a",{staticClass:"header-anchor",attrs:{href:"#vad-som-hander-i-svetsen","aria-hidden":"true"}},[n._v("#")]),n._v(" Vad som händer i svetsen")]),n._v(" "),e("p",[n._v("Om man nu i stället studerar svetsen, finner man att den från början är ett smältbad, bestående av en blandning av tillsats- och grundmaterial. När temperaturen sjunker under ca 1.500 °C, börjar smältan att stelna. Detta stelnande sker vinkelrätt från smältgränsen in mot svetsens mitt, i form av fingerliknande austenitkorn, dendriter.")]),n._v(" "),e("p",[n._v("Austeniter som har mycket låg löslighet för föroreningar kommer att pressa dessa dendriter framför sig – mot centrum av svetsen (bilden nedan.)")]),n._v(" "),e("p",[n._v("Ett annat fenomen som uppstår när en svets stelnar, är att de varma partierna kommer att krympa. Om man svetsar i en V-fog som i bilden nedan, har man störst smälta på toppsidan. Där kommer därför den största krympningen att ske, och arbetsstyckets delar kommer – när svetsen stelnat – inte längre att vara plana, utan bilda en vinkel.")]),n._v(" "),e("p",[n._v("Om de två plåtarna är fast inspända kommer de dragkrafter som bockade arbetsstycket, att finnas kvar som dragspänningar i och vid sidan om svetsen. Sådana dragspänningar, egenspänningar, finns inte bara tvärs svetsen, utan även längs med och i tjockleksriktningen. Man bör därför komma ihåg att det alltid finns dragspänningar i en svets (om svetsen inte har avspänningsglödgats) som är lika stora som grundmaterialets sträckgräns.")])])},[],!1,null,null,null);t.default=r.exports}}]);